import type { SessionUser } from "./lib/session";
import type { AuthContext } from "./auth/context";

/** Hono environment. `Env` is generated by `wrangler types` (worker-configuration.d.ts). */
export interface AppEnv {
  Bindings: Env;
  Variables: {
    user: SessionUser | null;
    /** Resolved once per request by `authMiddleware` (null when signed out). */
    auth: AuthContext | null;
    /** Session cookie refreshes to append to the response (auth middleware). */
    authSetCookies: string[];
  };
}

// Secrets are not in wrangler.jsonc, so `wrangler types` does not see them.
// Set with `wrangler secret put <NAME> [--env <env>]` (`.dev.vars` locally; see `.dev.vars.example`).
interface RollingSecrets {
  HYPEROUTER_API_KEY?: string;
  /** Hyperouter webhook signing secret (`whsec_...`, Standard Webhooks) for `POST /api/hooks/hyperouter` (M4). */
  HYPEROUTER_WEBHOOK_SECRET?: string;
  // Auth (M1). BETTER_AUTH_SECRET is required outside development.
  BETTER_AUTH_SECRET?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  APPLE_CLIENT_ID?: string;
  /** Either a pre-signed client secret JWT, or APPLE_TEAM_ID + APPLE_KEY_ID + APPLE_PRIVATE_KEY to sign one. */
  APPLE_CLIENT_SECRET?: string;
  APPLE_TEAM_ID?: string;
  APPLE_KEY_ID?: string;
  APPLE_PRIVATE_KEY?: string;
  APPLE_APP_BUNDLE_IDENTIFIER?: string;
  // Email (M1).
  RESEND_API_KEY?: string;
  /** Bearer token for `GET /api/test/inbox` (only with EMAIL_PROVIDER=test-inbox, never production). */
  TEST_INBOX_TOKEN?: string;
  /** `off` silences the development email log (not a secret; optional). */
  EMAIL_LOG?: string;
  // Media (M3, D-008). HMAC key for signed private media URLs; required outside development.
  MEDIA_SIGNING_KEY?: string;
  /** Origin of the private media host (e.g. `https://media.<domain>`); empty = this Worker's `/media/*` route. Not a secret. */
  PRIVATE_MEDIA_BASE_URL?: string;
  /** `off` skips the FFmpeg container in media processing (tests, local dev without Docker). Not a secret. */
  MEDIA_CONTAINER?: string;
  // Direct browser uploads to R2 (D-011): S3 API credentials (an R2 API token scoped to the media bucket).
  R2_ACCESS_KEY_ID?: string;
  R2_SECRET_ACCESS_KEY?: string;
  /** Vars (wrangler.jsonc): account id and the name of the bucket bound as MEDIA. */
  R2_ACCOUNT_ID?: string;
  R2_BUCKET_NAME?: string;
  // Billing (M2). Stripe secret key (sk_live_/sk_test_/rk_) and webhook signing secret (whsec_).
  STRIPE_SECRET_KEY?: string;
  STRIPE_WEBHOOK_SECRET?: string;
  /** Optional: pin a Stripe API version (e.g. "2025-09-30.clover"); unset = the account default. */
  STRIPE_API_VERSION?: string;
  /** Optional: Stripe API origin override (tests, stripe-mock). */
  STRIPE_API_BASE?: string;
  /** Not a secret (var or secret): address that receives Help → Send feedback; empty = stored in D1 only. */
  FEEDBACK_TO?: string;
}

declare global {
  interface Env extends RollingSecrets {}
  namespace Cloudflare {
    interface Env extends RollingSecrets {}
  }
}
